def statusuri_noi(apps, schema_editor):
    P = apps.get_model("platforma", "Proiect")
    N = apps.get_model("platforma", "Nomenclator")
    for p in P.objects.all():
        vechi = p.status
        if vechi in ("Finalizat",):
            nou = "Finalizat"
        elif vechi in ("Inactiv", "Anulat"):
            nou = "Anulat"
        elif p.stare_rz == "aprobat" or p.revizie_rz:
            nou = "În execuție"
        else:
            nou = ""  # devine „În execuție” la avizarea Raportului Zero
        if nou != vechi:
            P.objects.filter(pk=p.pk).update(status=nou)
    N.objects.filter(tip="status_proiect").delete()
    for i, v in enumerate(["În execuție", "Finalizat", "Anulat"]):
        N.objects.create(tip="status_proiect", valoare=v, ordine=i, activ=True)


def inapoi(apps, schema_editor):
    P = apps.get_model("platforma", "Proiect")
    P.objects.filter(status__in=["În execuție", ""]).update(status="In lucru")
    P.objects.filter(status="Anulat").update(status="Inactiv")


